// If the input vector is empty, return an empty vector
if (points.empty()) {
    return std::vector<Point2d>();
}

// Create a copy of the points to sort
std::vector<Point2d> sortedPoints = points;

// Sort the points lexicographically (first by x, then by y)
std::sort(sortedPoints.begin(), sortedPoints.end());

// If all points are the same, return a single point
if (sortedPoints.front() == sortedPoints.back()) {
    return std::vector<Point2d>(1, sortedPoints.front());
}

// Initialize the convex hull with the first two points
std::vector<Point2d> hull;
hull.reserve(sortedPoints.size() + 1);

// Process lower hull
for (size_t i = 0; i < sortedPoints.size(); ++i) {
    while (hull.size() >= 2 &&
           !isPointAtRight(hull[hull.size()-2], hull.back(), sortedPoints[i])) {
        hull.pop_back();
    }
    hull.push_back(sortedPoints[i]);
}

// Process upper hull
size_t lowerHullSize = hull.size();
for (size_t i = sortedPoints.size() - 1; i != (size_t)-1; --i) {
    while (hull.size() > lowerHullSize &&
           !isPointAtRight(hull[hull.size()-2], hull.back(), sortedPoints[i])) {
        hull.pop_back();
    }
    hull.push_back(sortedPoints[i]);
}

// Remove duplicate point (the first point is also the last)
hull.pop_back();

return hull;

